Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='growthmendbyrestating', at=datetime(2026, 11, 25, 0, 0, 0), actor='assistant', title='A growth check failing by a few tokens after a merge is mended by restating one Reading-growth, not by cutting code', body='When the growth check of a train fails by a few tokens after a merge of several pull requests, restate the Reading-growth line of one description by the figure that the check names, and say why. Do not cut code or comments from a merged change to close a gap that the merge made.', rationale='Each pull request pays for its own growth against its own base, so a merge of several can add a few tokens that no single pull request caused. Restating one declared figure records the true growth. Cutting code that a reviewer already accepted adds risk to pay for a rounding of the sum.', supersedes=()))